#include "kernels.h"

// The baseline: loops in the order i, j, d.
void dist_base(const float* P, int M, int D, float* out) {
    for (int i = 0; i < M; i++)
        for (int j = 0; j < M; j++) {
            float s = 0.0f;
            for (int d = 0; d < D; d++) {
                float t = P[d * M + i] - P[d * M + j];
                s += t * t;
            }
            out[(size_t)i * M + j] = s;
        }
}
